// @vitest-environment node
import { readFileSync } from "node:fs"
import { describe, expect, it } from "vitest"
import { compararSecuencias, type Opcode } from "@/lib/dominio/secuencias"

// Node, not jsdom: jsdom's URL breaks `new URL(..., import.meta.url)` for reading the fixture.
// Golden cases generated by tests/fixtures/difflib/generar.py (see its docstring to regenerate).
type CasoDorado = { a: string; b: string; ratio: number; opcodes: Opcode[] }

const CASOS: CasoDorado[] = JSON.parse(
  readFileSync(new URL("../fixtures/difflib/casos.json", import.meta.url), "utf-8"),
)

describe("compararSecuencias contra los casos dorados de difflib", () => {
  it.each(CASOS.map((caso) => [caso.a, caso.b, caso] as const))("%j vs %j", (_a, _b, { a, b, ratio, opcodes }) => {
    const resultado = compararSecuencias(a.split(""), b.split(""))
    expect(resultado.ratio).toBe(ratio)
    expect(resultado.opcodes).toEqual(opcodes)
  })
})
